from pathlib import Path
import json
J=Path(__file__).resolve().parents[1];S=json.loads((J/'design/study.json').read_text());d3=(J/'assets/d3.v7.min.js').read_text()
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fruchter — Rule-Based Overlap</title><style>*{box-sizing:border-box}body{margin:0;color:#242e31;background:white;font:15px/1.6 system-ui,sans-serif}header{padding:26px 4vw 20px;border-bottom:1px solid #ddd}h1{font-size:clamp(25px,4vw,42px);font-weight:500;line-height:1.1;margin:8px 0 15px}p{max-width:950px}main{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:28px;padding:24px 4vw}svg{width:100%;max-height:80vh;border:1px solid #ddd}select,button{font:inherit;padding:9px;background:white;color:inherit;border:1px solid #9ba8a1;border-radius:3px}select{width:100%}label{display:block;margin:12px 0 5px}input{accent-color:#bc6b3f;margin-right:8px}button{cursor:pointer;margin:12px 0}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.metrics{background:#f2f4ef;padding:14px;margin:20px 0}small{display:block;color:#647174}#rule{color:#ac583e}button:hover{background:#f4e8da}@media(max-width:780px){main{grid-template-columns:1fr}svg{max-height:65vh}header{padding-top:16px}}</style><header><small>FRUCHTER HOUSE / FIVE RULES / NINE PARAMETER CASES</small><h1>What creates the overlap?</h1><p>공통 모듈, 중심 반경, 동일한 회전 위상에서 출발합니다. 회색은 한 겹, 흙빛은 정확히 두 겹, 붉은색은 세 겹입니다. 원래 외곽을 재적용한 비교도 포함했습니다.</p></header><main><div><svg id="plan" viewBox="0 0 900 800" role="img" aria-label="규칙 기반 중첩 모델 비교"></svg></div><aside><label for="model">배치 규칙</label><select id="model"><option value="M1">M1 동심 중첩</option><option value="M2">M2 교대 연쇄</option><option value="M3">M3 대칭 방사</option><option value="M4" selected>M4 동일 위상 회전 / 선정</option><option value="M5">M5 둘레 순환</option><option value="PARAM">반경·회전 조합 비교</option><option value="R0">원래 외곽에 같은 규칙 재적용</option></select><div class="row" id="params"><div><label for="radius">중심 반경 R [u]</label><select id="radius"><option value="0.4">0.40</option><option value="0.45" selected>0.45</option><option value="0.5">0.50</option></select></div><div><label for="phase">공통 위상 φ</label><select id="phase"><option value="0">0°</option><option value="15" selected>15°</option><option value="30">30°</option></select></div></div><label><input id="cut" type="checkbox" checked>세 겹만 비우기</label><label><input id="axes" type="checkbox" checked>배치 원·장축·원 모듈 경계</label><label><input id="details" type="checkbox">선정안 벽·가구·연결 경로</label><p id="rule" aria-live="polite"></p><div class="metrics" id="metrics"></div><p id="comment"></p><button id="download">현재 도형 SVG 저장</button><small>u = 원도에서 추출한 세 공간군의 평균 면적의 제곱근. 미터가 아닙니다. 정규화한 공통 모듈은 1.25u × 0.80u입니다. 내접원 지름은 통로 유효 폭이나 법규 적합성의 증명이 아닙니다.</small></aside></main><script>__D3__</script><script>
const S=__DATA__,svg=d3.select('#plan'),tx=p=>[450+p[0]*220,370-p[1]*220];
const dpath=g=>[g.outer,...(g.holes||[])].map(ps=>'M'+ps.map(p=>tx(p).join(',')).join('L')+'Z').join('');
function shapes(gs,fill,stroke='#242e31',lw=1.6,dash=null){return svg.append('g').selectAll('path').data(gs).join('path').attr('d',dpath).attr('fill',fill).attr('fill-rule','evenodd').attr('stroke',stroke).attr('stroke-width',lw).attr('stroke-dasharray',dash)}
function line(ps,c,w=1.4,dash=null){svg.append('path').attr('d',d3.line()(ps.map(tx))).attr('fill','none').attr('stroke',c).attr('stroke-width',w).attr('stroke-dasharray',dash)}
function txt(x,y,t,size=15,c='#242e31'){svg.append('text').attr('x',x).attr('y',y).attr('font-family','sans-serif').attr('font-size',size).attr('fill',c).text(t)}
const comments={M1:'공통 중심은 크지만 독립 영역이 줄어듭니다. 중앙을 비우면 원래 세 모듈 면적 합의 약 21.5%가 남습니다.',M2:'공유 접점 두 개는 넓습니다. A에서 C로 가려면 B를 지나야 하므로 중심성이 중간 군에 집중됩니다.',M3:'회전 대칭과 반사 대칭이 성립합니다. M4보다 공유 접점이 넓고, 긴 축은 곧바로 공통 중심을 향합니다.',M4:'장축이 두 겹 접점을 먼저 만납니다. 한 겹은 독립 활동, 두 겹은 공유 방, 세 겹은 비움으로 우선 발전시킨 안입니다.',M5:'자연 중정과 세 공유 접점을 형성하며 면적 보존에 유리합니다. 세 겹 중첩을 비우는 원리와는 다릅니다.',R0:'원래 외곽과 개별 면적을 유지해 같은 배치 규칙을 적용했습니다. 접점 세 개는 유지되지만 중앙 비움은 작고 정확한 회전 대칭은 사라집니다.',PARAM:'같은 모듈에서 R과 φ만 바꾼 9개 사전 계산 사례입니다. 선택 값 밖의 연속적인 성능 최적화를 의미하지 않습니다.'};
function current(){const id=document.querySelector('#model').value;if(id==='R0')return S.original_outline_check;if(id==='PARAM')return S.parameter_grid.find(m=>m.radius===+document.querySelector('#radius').value&&m.phase===+document.querySelector('#phase').value);return S.models.find(m=>m.id===id)}
function render(){const id=document.querySelector('#model').value;document.querySelector('#params').style.display=id==='PARAM'?'grid':'none';const m=current(),cut=document.querySelector('#cut').checked,showAxes=document.querySelector('#axes').checked;svg.selectAll('*').remove();svg.append('rect').attr('width',900).attr('height',800).attr('fill','white');txt(28,34,m.id+' / '+m.name,22);txt(28,61,m.rule,14,'#647174');shapes(cut?m.floor:m.envelope,'#e2e5e3');Object.values(m.double).forEach(g=>shapes(g,'#e8bd9d','#bc6b3f',1));shapes(m.triple,cut?'white':'#a9524d',cut?'#44846c':'#a9524d',2);shapes(m.natural,'white','#44846c',2);
if(showAxes){if(m.radius){svg.append('circle').attr('cx',450).attr('cy',370).attr('r',m.radius*220).attr('fill','none').attr('stroke','#477ca0').attr('stroke-width',1)}for(const k of 'ABC'){shapes(m.regions[k],'none','#7a8982',1,'5 4');const c=m.centres[k],a=m.angles[k]*Math.PI/180;line([-1,1].map(v=>[c[0]+v*.75*Math.cos(a),c[1]+v*.75*Math.sin(a)]),'#477ca0',1,'7 4');const p=tx(c);txt(p[0]-4,p[1]-5,k,15)}}
const isSelected=m.id==='M4'||(m.radius===.45&&m.phase===15);document.querySelector('#details').disabled=!isSelected||!cut;
if(isSelected&&cut&&document.querySelector('#details').checked){S.plan.walls.forEach(w=>line([w.a,w.b],w.kind==='glazing'?'#477ca0':'#242e31',w.kind==='wall'?3.2:1.3));S.plan.furniture.forEach(f=>shapes(f.geometry,'white','#242e31',1.1));Object.values(S.plan.routes).forEach(ps=>line(ps,'#bc6b3f',1.5,'6 4'))}
const q=m.metrics;d3.select('#rule').text(m.rule);d3.select('#metrics').html(`삼중 영역: ${q.triple.toFixed(3)} u²<br>정확히 두 겹인 접점 합: ${q.double_total.toFixed(3)} u²<br>현재 실내 도형 면적: ${(cut?q.floor_after_triple_cut:q.union).toFixed(3)} u²<br>세 겹 삭제 후 실내 비율: ${(q.floor_after_triple_cut/3*100).toFixed(1)}%<br>자연 발생한 빈 곳: ${q.natural_void.toFixed(3)} u²`);d3.select('#comment').text(comments[id]);line([[-1.7,-1.55],[-.7,-1.55]],'#242e31',2.5);txt(76,735,'0');txt(296,735,'1 u');txt(380,735,'RELATIVE UNITS / DESIGN HYPOTHESIS',13,'#647174');svg.attr('data-model',m.id).attr('data-cut',cut)}
d3.select('#model').on('change',render);d3.selectAll('#radius,#phase').on('change',()=>{document.querySelector('#model').value='PARAM';render()});d3.selectAll('input').on('change',render);d3.select('#download').on('click',()=>{const n=svg.node().cloneNode(true);n.setAttribute('xmlns','http://www.w3.org/2000/svg');const u=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(n)],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=u;a.download='Fruchter_'+current().id+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});render();
</script></html>'''
(J/'output/Overlap_Rule_Explorer.html').write_text(html.replace('__D3__',d3).replace('__DATA__',json.dumps(S,ensure_ascii=False)),encoding='utf-8');print('Explorer generated')
